#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "dice_lcg.h"

static int failures = 0;
static int total = 0;

static void fail(const char *label, const char *msg) {
    failures++;
    if (failures <= 8) printf("  %s: %s\n", label, msg);
}

static void check_err(const char *label, int rc) {
    total++;
    if (rc == 0) fail(label, "expected an error");
}

static void check_str(const char *label, int rc, const char *got, const char *want) {
    total++;
    char msg[600];
    if (rc != 0) { fail(label, "unexpected error"); return; }
    if (strcmp(got, want) != 0) {
        snprintf(msg, sizeof msg, "want \"%s\", got \"%s\"", want, got);
        fail(label, msg);
    }
}

static void check_int(const char *label, int rc, int64_t got, int64_t want) {
    total++;
    char msg[200];
    if (rc != 0) { fail(label, "unexpected error"); return; }
    if (got != want) {
        snprintf(msg, sizeof msg, "want %lld, got %lld", (long long) want, (long long) got);
        fail(label, msg);
    }
}

int main(void) {
    {  int64_t got = (int64_t) dice_lcg_step(0u); check_int("step#0", 0, got, INT64_C(2891336453)); }
    {  int64_t got = (int64_t) dice_lcg_output(1u); check_int("output#1", 0, got, INT64_C(277803675)); }
    {  int64_t got = (int64_t) dice_lcg_draw(42u, 0u); check_int("draw#2", 0, got, INT64_C(1223963391)); }
    {  uint32_t out = 0; int rc = dice_lcg_roll(42u, 0u, 6u, &out); check_int("roll#3", rc, (int64_t) out, INT64_C(4)); }
    {  int32_t out = 0; int rc = dice_lcg_sum_dice(7u, "3d6+2", &out); check_int("sum_dice#4", rc, (int64_t) out, INT64_C(10)); }
    {  char out[8192]; int rc = dice_lcg_shuffle(42u, 5u, out, sizeof out); check_str("shuffle#5", rc, out, "2,3,4,0,1"); }
    {  int64_t got = (int64_t) dice_lcg_draw(0u, 1u); check_int("draw#6", 0, got, INT64_C(582399676)); }
    {  uint32_t out = 0; int rc = dice_lcg_roll(1u, 3u, 20u, &out); check_int("roll#7", rc, (int64_t) out, INT64_C(3)); }
    {  int32_t out = 0; int rc = dice_lcg_sum_dice(1u, "d20", &out); check_int("sum_dice#8", rc, (int64_t) out, INT64_C(13)); }
    {  char out[8192]; int rc = dice_lcg_shuffle(7u, 10u, out, sizeof out); check_str("shuffle#9", rc, out, "2,5,1,9,8,7,4,6,3,0"); }
    if (failures) {
        printf("%d of %d vectors failed\n", failures, total);
        return 1;
    }
    printf("ok %d vectors\n", total);
    return 0;
}

