        if m.group(3) == "-":
            modifier = -modifier
    s, total = seed, 0
    for _ in range(count):
        s, r = _bounded(s, sides)
        total += r + 1
    return total + modifier


def shuffle(seed, n):
    if n > 500:
        raise ValueError("too many items")
    a = list(range(n))
    s = seed
    for i in range(n - 1, 0, -1):
        s, j = _bounded(s, i + 1)
